140  /* Search for an adjacent run in the forward or backward direction.
   141     It uses the next_isolate and prev_isolate run for short circuited searching.
   142   */
   143
   144  /* The static sentinel is used to signal the end of an isolating
   145     sequence */
   146  static FriBidiRun sentinel = { NULL, NULL, 0,0, FRIBIDI_TYPE_SENTINEL, -1,-1,FRIBIDI_NO_BRACKET, NULL, NULL };
   147
   148  static FriBidiRun *get_adjacent_run(FriBidiRun *list, fribidi_boolean forward, fribidi_boolean skip_neutral)
   149  {
   150    FriBidiRun *ppp = forward ? list->next_isolate : list->prev_isolate;
   151    if (!ppp)
   152      return &sentinel;
   153
   154    while (ppp)
   155      {
   156        FriBidiCharType ppp_type = RL_TYPE (ppp);
   157
   158        if (ppp_type == FRIBIDI_TYPE_SENTINEL)
   159          break;
   160
   161        /* Note that when sweeping forward we continue one run
   162           beyond the PDI to see what lies behind. When looking
   163           backwards, this is not necessary as the leading isolate
   164           run has already been assigned the resolved level. */
   165        if (ppp->isolate_level > list->isolate_level   /* <- How can this be true? */
   166            || (forward && ppp_type == FRIBIDI_TYPE_PDI)
   167            || (skip_neutral && !FRIBIDI_IS_STRONG(ppp_type)))
   168          {
   169            ppp = forward ? ppp->next_isolate : ppp->prev_isolate;
   170            if (!ppp)
   171              ppp = &sentinel;
   172
   173            continue;
   174          }
   175        break;
   176      }
   177
   178    return ppp;
   179  }
