   214  static void
   215  print_types_re (
   216    const FriBidiRun *pp
   217  )
   218  {
   219    fribidi_assert (pp);
   220
   221    MSG ("  Run types  : ");
   222    for_run_list (pp, pp)
   223    {
   224      MSG6 ("%d:%d(%s)[%d,%d] ",
   225            pp->pos, pp->len, fribidi_get_bidi_type_name (pp->type), pp->level, pp->isolate_level);
   226    }
   227    MSG ("\n");
   228  }
   229
   230  static void
   231  print_resolved_levels (
   232    const FriBidiRun *pp
   233  )
   234  {
   235    fribidi_assert (pp);
   236
   237    MSG ("  Res. levels: ");
   238    for_run_list (pp, pp)
   239    {
   240      register FriBidiStrIndex i;
   241      for (i = RL_LEN (pp); i; i--)
   242        MSG2 ("%c", fribidi_char_from_level (RL_LEVEL (pp)));
   243    }
   244    MSG ("\n");
   245  }
   246
   247  static void
   248  print_resolved_types (
   249    const FriBidiRun *pp
   250  )
   251  {
   252    fribidi_assert (pp);
   253
   254    MSG ("  Res. types : ");
   255    for_run_list (pp, pp)
   256    {
   257      FriBidiStrIndex i;
   258      for (i = RL_LEN (pp); i; i--)
   259        MSG2 ("%s ", fribidi_get_bidi_type_name (pp->type));
   260    }
   520    /* input and output */
   521    FriBidiParType *pbase_dir,
   522    /* output */
   523    FriBidiLevel *embedding_levels
   524  )
   525  {
   526    FriBidiLevel base_level, max_level = 0;
   527    FriBidiParType base_dir;
   528    FriBidiRun *main_run_list = NULL, *explicits_list = NULL, *pp;
   529    fribidi_boolean status = false;
   530    int max_iso_level = 0;
   531
   532    if UNLIKELY
   533      (!len)
   534      {
   535        status = true;
   536        goto out;
   537      }
   538
   539    DBG ("in fribidi_get_par_embedding_levels");
   540
   541    fribidi_assert (bidi_types);
   542    fribidi_assert (pbase_dir);
   543    fribidi_assert (embedding_levels);
   544
   545    /* Determinate character types */
   546    {
   547      /* Get run-length encoded character types */
   548      main_run_list = run_list_encode_bidi_types (bidi_types, bracket_types, len);
   549      if UNLIKELY
   550        (!main_run_list) goto out;
   551    }
   552
   553    /* Find base level */
   554    /* If no strong base_dir was found, resort to the weak direction
   555       that was passed on input. */
   556    base_level = FRIBIDI_DIR_TO_LEVEL (*pbase_dir);
   557    if (!FRIBIDI_IS_STRONG (*pbase_dir))
   558      /* P2. P3. Search for first strong character and use its direction as
   559         base direction */
   560      {
   561        int valid_isolate_count = 0;
   562        for_run_list (pp, main_run_list)
   563          {
   564            if (RL_TYPE(pp) == FRIBIDI_TYPE_PDI)
   565              {
   566                /* Ignore if there is no matching isolate */
   567                if (valid_isolate_count>0)
   568                  valid_isolate_count--;
   569              }
   570            else if (FRIBIDI_IS_ISOLATE(RL_TYPE(pp)))
   571              valid_isolate_count++;
   572            else if (valid_isolate_count==0 && FRIBIDI_IS_LETTER (RL_TYPE (pp)))
   573              {
   574                base_level = FRIBIDI_DIR_TO_LEVEL (RL_TYPE (pp));
   575                *pbase_dir = FRIBIDI_LEVEL_TO_DIR (base_level);
   576                break;
   577              }
   578          }
   579      }
   580    base_dir = FRIBIDI_LEVEL_TO_DIR (base_level);
   581    DBG2 ("  base level : %c", fribidi_char_from_level (base_level));
   582    DBG2 ("  base dir   : %s", fribidi_get_bidi_type_name (base_dir));
   583
   584  # if DEBUG
   585    if UNLIKELY
   586      (fribidi_debug_status ())
   587      {
   588        print_types_re (main_run_list);
   589      }
   590  # endif /* DEBUG */
   591
   592    /* Explicit Levels and Directions */
   593    DBG ("explicit levels and directions");
   594    {
   595      FriBidiLevel level, new_level = 0;
   596      int isolate_level = 0;
   597      FriBidiCharType override, new_override;
   598      FriBidiStrIndex i;
   599      int stack_size, over_pushed, first_interval;
   600      int valid_isolate_count = 0;
   601      int isolate_overflow = 0;
   602      int isolate = 0; /* The isolate status flag */
   603      struct
   604      {
   605        FriBidiCharType override; /* only LTR, RTL and ON are valid */
   606        FriBidiLevel level;
   607        int isolate;
   608        int isolate_level;
   609      } status_stack[FRIBIDI_BIDI_MAX_RESOLVED_LEVELS];
   610      FriBidiRun temp_link;
   611      FriBidiRun *run_per_isolate_level[FRIBIDI_BIDI_MAX_RESOLVED_LEVELS];
   612      int prev_isolate_level = 0; /* When running over the isolate levels, remember the previous level */
   613
   614      memset(run_per_isolate_level, 0, sizeof(run_per_isolate_level[0])
   615             * FRIBIDI_BIDI_MAX_RESOLVED_LEVELS);
   616
   617  /* explicits_list is a list like main_run_list, that holds the explicit
   618     codes that are removed from main_run_list, to reinsert them later by
   619     calling the shadow_run_list.
   620  */
   621      explicits_list = new_run_list ();
   622      if UNLIKELY
   623        (!explicits_list) goto out;
   624
   625      /* X1. Begin by setting the current embedding level to the paragraph
   626         embedding level. Set the directional override status to neutral,
   627         and directional isolate status to false.
   628
   629         Process each character iteratively, applying rules X2 through X8.
   630         Only embedding levels from 0 to 123 are valid in this phase. */
   631
   632      level = base_level;
   633      override = FRIBIDI_TYPE_ON;
   634      /* stack */
   635      stack_size = 0;
   636      over_pushed = 0;
   637      first_interval = 0;
   638      valid_isolate_count = 0;
   639      isolate_overflow = 0;
   640
   790            /* X6. For all types besides RLE, LRE, RLO, LRO, and PDF:
   791               a. Set the level of the current character to the current
   792               embedding level.
   793               b. Whenever the directional override status is not neutral,
   794               reset the current character type to the directional override
   795               status. */
   796            RL_LEVEL (pp) = level;
   797            if (!FRIBIDI_IS_NEUTRAL (override))
   798              RL_TYPE (pp) = override;
   799          }
   800      }
   801
   802      /* Build the isolate_level connections */
   803      prev_isolate_level = 0;
   804      for_run_list (pp, main_run_list)
   805      {
   806        int isolate_level = RL_ISOLATE_LEVEL (pp);
   807        int i;
   808
   809        /* When going from an upper to a lower level, zero out all higher levels
   810           in order not erroneous connections! */
   811        if (isolate_level<prev_isolate_level)
   812          for (i=isolate_level+1; i<=prev_isolate_level; i++)
   813            run_per_isolate_level[i]=0;
   814        prev_isolate_level = isolate_level;
   815
   816        if (run_per_isolate_level[isolate_level])
   817          {
   818            run_per_isolate_level[isolate_level]->next_isolate = pp;
   819            pp->prev_isolate = run_per_isolate_level[isolate_level];
   820          }
   821        run_per_isolate_level[isolate_level] = pp;
   822      }
   823
   824      /* Implementing X8. It has no effect on a single paragraph! */
   825      level = base_level;
   826      override = FRIBIDI_TYPE_ON;
   827      stack_size = 0;
   828      over_pushed = 0;
   829    }
   830    /* X10. The remaining rules are applied to each run of characters at the
   831       same level. For each run, determine the start-of-level-run (sor) and
   832       end-of-level-run (eor) type, either L or R. This depends on the
   833       higher of the two levels on either side of the boundary (at the start
   834       or end of the paragraph, the level of the 'other' run is the base
   835       embedding level). If the higher level is odd, the type is R, otherwise
   836       it is L. */
   837    /* Resolving Implicit Levels can be done out of X10 loop, so only change
   838       of Resolving Weak Types and Resolving Neutral Types is needed. */
   839
   840    compact_list (main_run_list);
   841
   842  # if DEBUG
   843    if UNLIKELY
   844      (fribidi_debug_status ())
   845      {
   846        print_types_re (main_run_list);
   847        print_bidi_string (bidi_types, len);
   848        print_resolved_levels (main_run_list);
   849        print_resolved_types (main_run_list);
   850      }
   851  # endif /* DEBUG */
   852
   853    /* 4. Resolving weak types. Also calculate the maximum isolate level */
   854    max_iso_level = 0;
   855    DBG ("4a. resolving weak types");
   856    {
   857      int last_strong_stack[FRIBIDI_BIDI_MAX_RESOLVED_LEVELS];
   858      FriBidiCharType prev_type_orig;
   859      fribidi_boolean w4;
   860
   861      last_strong_stack[0] = base_dir;
   862
   863      for_run_list (pp, main_run_list)
   864      {
   865        register FriBidiCharType prev_type, this_type, next_type;
   866        FriBidiRun *ppp_prev, *ppp_next;
   867        int iso_level;
   868
   869        ppp_prev = get_adjacent_run(pp, false, false);
   870        ppp_next = get_adjacent_run(pp, true, false);
   871
   872        this_type = RL_TYPE (pp);
   873        iso_level = RL_ISOLATE_LEVEL(pp);
   874
   875        if (iso_level > max_iso_level)
   876          max_iso_level = iso_level;
   877
   878        if (RL_LEVEL(ppp_prev) == RL_LEVEL(pp))
   879          prev_type = RL_TYPE(ppp_prev);
   880        else
   881          prev_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_prev), RL_LEVEL(pp)));
   882
   883        if (RL_LEVEL(ppp_next) == RL_LEVEL(pp))
   884          next_type = RL_TYPE(ppp_next);
   885        else
   886          next_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_next), RL_LEVEL(pp)));
   887
   888        if (FRIBIDI_IS_STRONG (prev_type))
   889          last_strong_stack[iso_level] = prev_type;
   890
   891        /* W1. NSM
   892           Examine each non-spacing mark (NSM) in the level run, and change the
   893           type of the NSM to the type of the previous character. If the NSM
   894           is at the start of the level run, it will get the type of sor. */
   895        /* Implementation note: it is important that if the previous character
   896           is not sor, then we should merge this run with the previous,
   897           because of rules like W5, that we assume all of a sequence of
   898           adjacent ETs are in one FriBidiRun. */
   899        if (this_type == FRIBIDI_TYPE_NSM)
   900          {
   901            /* New rule in Unicode 6.3 */
   902            if (FRIBIDI_IS_ISOLATE (RL_TYPE (pp->prev)))
   903                RL_TYPE(pp) = FRIBIDI_TYPE_ON;
   904
   905            if (RL_LEVEL (ppp_prev) == RL_LEVEL (pp))
   906              {
   907                if (ppp_prev == pp->prev)
   908                  pp = merge_with_prev (pp);
   909              }
   910            else
   911              RL_TYPE (pp) = prev_type;
   912
   913            if (prev_type == next_type && RL_LEVEL (pp) == RL_LEVEL (pp->next))
   914              {
   915                if (ppp_next == pp->next)
   916                  pp = merge_with_prev (pp->next);
   917              }
   918            continue;             /* As we know the next condition cannot be true. */
   919          }
   920
   921        /* W2: European numbers. */
   922        if (this_type == FRIBIDI_TYPE_EN && last_strong_stack[iso_level] == FRIBIDI_TYPE_AL)
   923          {
   924            RL_TYPE (pp) = FRIBIDI_TYPE_AN;
   925
   926            /* Resolving dependency of loops for rules W1 and W2, so we
   927               can merge them in one loop. */
   928            if (next_type == FRIBIDI_TYPE_NSM)
   929              RL_TYPE (ppp_next) = FRIBIDI_TYPE_AN;
   930          }
   931      }
   932
   933  # if DEBUG
   934    if UNLIKELY
   935      (fribidi_debug_status ())
   936      {
   937        print_resolved_levels (main_run_list);
   938        print_resolved_types (main_run_list);
   939      }
   940  # endif /* DEBUG */
   941
   942      /* The last iso level is used to invalidate the the last strong values when going from
   943         a higher to a lower iso level. When this occur, all "last_strong" values are
   944         set to the base_dir. */
   945      last_strong_stack[0] = base_dir;
   946
   947      DBG ("4b. resolving weak types. W4 and W5");
   948
   949      /* Resolving dependency of loops for rules W4 and W5, W5 may
   950         want to prevent W4 to take effect in the next turn, do this
   951         through "w4". */
   952      w4 = true;
   953      /* Resolving dependency of loops for rules W4 and W5 with W7,
   954         W7 may change an EN to L but it sets the prev_type_orig if needed,
   955         so W4 and W5 in next turn can still do their works. */
   956      prev_type_orig = FRIBIDI_TYPE_ON;
   957
   958      /* Each isolate level has its own memory of the last strong character */
   959      for_run_list (pp, main_run_list)
   960      {
   961        register FriBidiCharType prev_type, this_type, next_type;
   962        int iso_level;
   963        FriBidiRun *ppp_prev, *ppp_next;
   964
   965        this_type = RL_TYPE (pp);
   966        iso_level = RL_ISOLATE_LEVEL(pp);
   967
   968        ppp_prev = get_adjacent_run(pp, false, false);
   969        ppp_next = get_adjacent_run(pp, true, false);
   970
   971        if (RL_LEVEL(ppp_prev) == RL_LEVEL(pp))
   972          prev_type = RL_TYPE(ppp_prev);
   973        else
   974          prev_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_prev), RL_LEVEL(pp)));
   975
   976        if (RL_LEVEL(ppp_next) == RL_LEVEL(pp))
   977          next_type = RL_TYPE(ppp_next);
   978        else
   979          next_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_next), RL_LEVEL(pp)));
   980
   981        if (FRIBIDI_IS_STRONG (prev_type))
   982          last_strong_stack[iso_level] = prev_type;
   983
   984        /* W2 ??? */
   985
   986        /* W3: Change ALs to R. */
   987        if (this_type == FRIBIDI_TYPE_AL)
   988          {
   989            RL_TYPE (pp) = FRIBIDI_TYPE_RTL;
   990            w4 = true;
   991            prev_type_orig = FRIBIDI_TYPE_ON;
   992            continue;
   993          }
   994
   995        /* W4. A single european separator changes to a european number.
   996           A single common separator between two numbers of the same type
   997           changes to that type. */
   998        if (w4
   999            && RL_LEN (pp) == 1 && FRIBIDI_IS_ES_OR_CS (this_type)
  1000            && FRIBIDI_IS_NUMBER (prev_type_orig)
  1001            && prev_type_orig == next_type
  1002            && (prev_type_orig == FRIBIDI_TYPE_EN
  1003                || this_type == FRIBIDI_TYPE_CS))
  1004          {
  1005            RL_TYPE (pp) = prev_type;
  1006            this_type = RL_TYPE (pp);
  1007          }
  1008        w4 = true;
  1009
  1010        /* W5. A sequence of European terminators adjacent to European
  1011           numbers changes to All European numbers. */
  1012        if (this_type == FRIBIDI_TYPE_ET
  1013            && (prev_type_orig == FRIBIDI_TYPE_EN
  1014                || next_type == FRIBIDI_TYPE_EN))
  1015          {
  1016            RL_TYPE (pp) = FRIBIDI_TYPE_EN;
  1017            w4 = false;
  1018            this_type = RL_TYPE (pp);
  1019          }
  1020
  1021        /* W6. Otherwise change separators and terminators to other neutral. */
  1022        if (FRIBIDI_IS_NUMBER_SEPARATOR_OR_TERMINATOR (this_type))
  1023          RL_TYPE (pp) = FRIBIDI_TYPE_ON;
  1024
  1025        /* W7. Change european numbers to L. */
  1026        if (this_type == FRIBIDI_TYPE_EN && last_strong_stack[iso_level] == FRIBIDI_TYPE_LTR)
  1027          {
  1028            RL_TYPE (pp) = FRIBIDI_TYPE_LTR;
  1029            prev_type_orig = (RL_LEVEL (pp) == RL_LEVEL (pp->next) ?
  1030                              FRIBIDI_TYPE_EN : FRIBIDI_TYPE_ON);
  1031          }
  1032        else
  1033          prev_type_orig = PREV_TYPE_OR_SOR (pp->next);
  1034      }
  1035    }
  1036
  1037    compact_neutrals (main_run_list);
  1038
  1039  # if DEBUG
  1040    if UNLIKELY
  1220  # if DEBUG
  1221    if UNLIKELY
  1222      (fribidi_debug_status ())
  1223      {
  1224        print_resolved_levels (main_run_list);
  1225        print_resolved_types (main_run_list);
  1226      }
  1227  # endif /* DEBUG */
  1228    }
  1229
  1230    DBG ("resolving neutral types - N1+N2");
  1231    {
  1232      for_run_list (pp, main_run_list)
  1233      {
  1234        FriBidiCharType prev_type, this_type, next_type;
  1235        FriBidiRun *ppp_prev, *ppp_next;
  1236
  1237        ppp_prev = get_adjacent_run(pp, false, false);
  1238        ppp_next = get_adjacent_run(pp, true, false);
  1239
  1240        /* "European and Arabic numbers are treated as though they were R"
  1241           FRIBIDI_CHANGE_NUMBER_TO_RTL does this. */
  1242        this_type = FRIBIDI_CHANGE_NUMBER_TO_RTL (RL_TYPE (pp));
  1243
  1244        if (RL_LEVEL(ppp_prev) == RL_LEVEL(pp))
  1245          prev_type = FRIBIDI_CHANGE_NUMBER_TO_RTL (RL_TYPE(ppp_prev));
  1246        else
  1247          prev_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_prev), RL_LEVEL(pp)));
  1248
  1249        if (RL_LEVEL(ppp_next) == RL_LEVEL(pp))
  1250          next_type = FRIBIDI_CHANGE_NUMBER_TO_RTL (RL_TYPE(ppp_next));
  1251        else
  1252          next_type = FRIBIDI_LEVEL_TO_DIR(MAX(RL_LEVEL(ppp_next), RL_LEVEL(pp)));
  1253
  1254        if (FRIBIDI_IS_NEUTRAL (this_type))
  1255          RL_TYPE (pp) = (prev_type == next_type) ?
  1256            /* N1. */ prev_type :
  1257            /* N2. */ FRIBIDI_EMBEDDING_DIRECTION (pp);
  1258      }
  1259    }
  1260
  1261    compact_list (main_run_list);
  1262
  1263  # if DEBUG
  1264    if UNLIKELY
  1265      (fribidi_debug_status ())
  1266      {
  1267        print_resolved_levels (main_run_list);
  1268        print_resolved_types (main_run_list);
  1269      }
  1270  # endif /* DEBUG */
  1271
  1272    /* 6. Resolving implicit levels */
  1273    DBG ("resolving implicit levels");
  1274    {
  1275      max_level = base_level;
  1276
  1277      for_run_list (pp, main_run_list)
  1278      {
  1279        FriBidiCharType this_type;
  1280        int level;
  1281
  1282        this_type = RL_TYPE (pp);
  1283        level = RL_LEVEL (pp);
  1284
  1285        /* I1. Even */
  1286        /* I2. Odd */
  1287        if (FRIBIDI_IS_NUMBER (this_type))
  1288          RL_LEVEL (pp) = (level + 2) & ~1;
  1289        else
  1290          RL_LEVEL (pp) =
  1291            level +
  1292            (FRIBIDI_LEVEL_IS_RTL (level) ^ FRIBIDI_DIR_TO_LEVEL (this_type));
  1293
  1294        if (RL_LEVEL (pp) > max_level)
  1295          max_level = RL_LEVEL (pp);
  1296      }
  1297    }
  1298
  1299    compact_list (main_run_list);
  1300
  1301  # if DEBUG
  1302    if UNLIKELY
  1303      (fribidi_debug_status ())
  1304      {
  1305        print_bidi_string (bidi_types, len);
  1306        print_resolved_levels (main_run_list);
  1307        print_resolved_types (main_run_list);
  1308      }
  1309  # endif /* DEBUG */
  1310
  1311  /* Reinsert the explicit codes & BN's that are already removed, from the
  1312     explicits_list to main_run_list. */
  1313    DBG ("reinserting explicit codes");
  1314    if UNLIKELY
  1315      (explicits_list->next != explicits_list)
  1316      {
  1317        register FriBidiRun *p;
  1318        register fribidi_boolean stat =
  1319          shadow_run_list (main_run_list, explicits_list, true);
  1320        explicits_list = NULL;
  1321        if UNLIKELY
  1322          (!stat) goto out;
  1323
  1324        /* Set level of inserted explicit chars to that of their previous
  1325         * char, such that they do not affect reordering. */
  1326        p = main_run_list->next;
  1327        if (p != main_run_list && p->level == FRIBIDI_SENTINEL)
  1328          p->level = base_level;
  1329        for_run_list (p, main_run_list) if (p->level == FRIBIDI_SENTINEL)
  1330          p->level = p->prev->level;
  1331      }
  1332
  1333  # if DEBUG
  1334    if UNLIKELY
  1335      (fribidi_debug_status ())
  1336      {
  1337        print_types_re (main_run_list);
  1338        print_resolved_levels (main_run_list);
  1339        print_resolved_types (main_run_list);
  1340      }
  1341  # endif /* DEBUG */
  1342
  1343    DBG ("reset the embedding levels, 1, 2, 3.");
  1344    {
  1345      register int j, state, pos;
  1346      register FriBidiCharType char_type;
  1347      register FriBidiRun *p, *q, *list;
  1348
  1349      /* L1. Reset the embedding levels of some chars:
  1350         1. segment separators,
  1351         2. paragraph separators,
  1352         3. any sequence of whitespace characters preceding a segment
  1353            separator or paragraph separator, and
  1354         4. any sequence of whitespace characters and/or isolate formatting
  1355            characters at the end of the line.
  1356         ... (to be continued in fribidi_reorder_line()). */
  1357      list = new_run_list ();
  1358      if UNLIKELY
  1359        (!list) goto out;
  1360      q = list;
  1361      state = 1;
  1362      pos = len - 1;
  1363      for (j = len - 1; j >= -1; j--)
  1364        {
  1365          /* close up the open link at the end */
  1366          if (j >= 0)
  1367            char_type = bidi_types[j];
  1368          else
  1369            char_type = FRIBIDI_TYPE_ON;
  1370          if (!state && FRIBIDI_IS_SEPARATOR (char_type))
  1371            {
  1372              state = 1;
  1373              pos = j;
  1374            }
  1375          else if (state &&
  1376                   !(FRIBIDI_IS_EXPLICIT_OR_SEPARATOR_OR_BN_OR_WS(char_type)
  1377                     || FRIBIDI_IS_ISOLATE(char_type)))
  1378            {
  1379              state = 0;
  1380              p = new_run ();
  1381              if UNLIKELY
  1382                (!p)
  1383                {
  1384                  free_run_list (list);
  1385                  goto out;
  1386                }
  1387              p->pos = j + 1;
  1388              p->len = pos - j;
  1389              p->type = base_dir;
  1390              p->level = base_level;
  1391              move_node_before (p, q);
  1392              q = p;
  1393            }
  1394        }
  1395      if UNLIKELY
  1396        (!shadow_run_list (main_run_list, list, false)) goto out;
  1397    }
  1398
  1399  # if DEBUG
  1400    if UNLIKELY
  1401      (fribidi_debug_status ())
  1402      {
  1403        print_types_re (main_run_list);
  1404        print_resolved_levels (main_run_list);
  1405        print_resolved_types (main_run_list);
  1406      }
  1407  # endif /* DEBUG */
  1408
  1409    {
  1410      FriBidiStrIndex pos = 0;
  1411      for_run_list (pp, main_run_list)
  1412      {
  1413        register FriBidiStrIndex l;
  1414        register FriBidiLevel level = pp->level;
  1415        for (l = pp->len; l; l--)
  1416          embedding_levels[pos++] = level;
  1417      }
  1418    }
  1419
  1420    status = true;
  1421
  1422  out:
  1423    DBG ("leaving fribidi_get_par_embedding_levels");
  1424
  1425    if (main_run_list)
  1426      free_run_list (main_run_list);
  1427    if UNLIKELY
  1428      (explicits_list) free_run_list (explicits_list);
  1429
  1430    return status ? max_level + 1 : 0;
  1431  }
