  1434  static void
  1435  bidi_string_reverse (
  1436    FriBidiChar *str,
  1437    const FriBidiStrIndex len
  1438  )
  1439  {
  1440    FriBidiStrIndex i;
  1441
  1442    fribidi_assert (str);
  1443
  1444    for (i = 0; i < len / 2; i++)
  1445      {
  1446        FriBidiChar tmp = str[i];
  1447        str[i] = str[len - 1 - i];
  1448        str[len - 1 - i] = tmp;
  1449      }
  1450  }
